    "quote": "when using attribute numbers",
    "source": "PostgreSQL 14 release notes: Migration to Version 14",
    "release_of_change": "14"
   }
  ]
 },
 {
  "condition_id": "the_application_relies_on_has_column_pri_675e5f",
  "claim": "The application relies on has_column_privilege() raising an error for non-existent or dropped columns when given attribute numbers.",
  "evidence": [
   {
    "quote": "Previously such attribute numbers returned an invalid-column error.",
    "source": "PostgreSQL 14 release notes: Migration to Version 14",
    "release_of_change": "14"
   }
  ]
 }
]
